/// Host `_M_insert_aux` for 0xb740: doubling growth, move, append, free old.
fn vector2int16_insert_aux(vec: *mut StdVector2int16, value: *const u32) {
    use std::alloc::{Layout, alloc, dealloc};
    unsafe {
        let start = (*vec).start;
        let finish = (*vec).finish;
        let len = if start.is_null() {
            0
        } else {
            (finish as usize - start as usize) / 4
        };
        let cap = if start.is_null() {
            0
        } else {
            ((*vec).end_of_storage as usize - start as usize) / 4
        };
        let new_cap = if cap == 0 { 1 } else { cap * 2 };
        let layout = Layout::array::<u32>(new_cap).expect("vector growth layout");
        let new_start = alloc(layout) as *mut u32;
        if new_start.is_null() {
            std::alloc::handle_alloc_error(layout);
        }
        core::ptr::copy_nonoverlapping(start, new_start, len);
        *new_start.add(len) = *value;
        if !start.is_null() && cap > 0 {
            dealloc(start as *mut u8, Layout::array::<u32>(cap).expect("vector old layout"));
        }
        (*vec).start = new_start;
        (*vec).finish = new_start.add(len + 1);
        (*vec).end_of_storage = new_start.add(new_cap);
    }
}

